const express = require('express');
const Pool = require('pg-pool');

const app = express();

const tenantAuditPools = new Map();

function getAuditPool(tenantKey) {
  if (!tenantAuditPools.has(tenantKey)) {
    tenantAuditPools.set(
      tenantKey,
      new Pool({
        database: `audit_${tenantKey}`,
        host: 'audit-pg.internal',
        user: 'audit_service',
        password: process.env.AUDIT_PG_PASS
      })
    );
  }
  return tenantAuditPools.get(tenantKey);
}

app.get('/api/audit/logs/stream', async (req, res) => {
  if (!req.user || !req.user.tenantKey) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantKey, limit } = req.query;

  // Enforce that caller cannot access another tenant's audit database pool
  if (tenantKey && tenantKey !== req.user.tenantKey) {
    return res.status(403).json({ error: 'Access denied: cannot query audit logs of another tenant' });
  }

  const authorizedKey = req.user.tenantKey;
  const pool = getAuditPool(authorizedKey);

  try {
    const { rows } = await pool.query(
      'SELECT event_id, actor_id, action, resource, ip_address, created_at FROM system_audit_trail ORDER BY created_at DESC LIMIT $1',
      [Math.min(parseInt(limit, 10) || 50, 200)]
    );
    res.json({ tenantKey: authorizedKey, logs: rows });
  } catch (err) {
    res.status(500).json({ error: 'Failed to query audit database' });
  }
});

app.listen(9106);
